function pick(a){return a[Math.floor(Math.random()*a.length)];}
function fmt(v){const n=Math.abs(Math.round(v)),sign=v<0?'-':'';if(n>=1000000000)return sign+(n/1000000000).toLocaleString('vi-VN',{maximumFractionDigits:2})+' tỷ';if(n>=1000000)return sign+(n/1000000).toLocaleString('vi-VN',{maximumFractionDigits:1})+' tr';if(n>=1000)return sign+Math.round(n/1000).toLocaleString('vi-VN')+'k';return sign+n.toLocaleString('vi-VN')+'đ';}
function fmtDuration(m){m=Math.max(0,Math.round(m));const h=Math.floor(m/60),r=m%60;if(!h)return `${r} phút`;if(!r)return `${h} giờ`;return `${h}g ${r}p`;}
function timeLabel(m=state?.clock||DEFAULT_WAKE){const x=((Math.round(m)%1440)+1440)%1440;return `${String(Math.floor(x/60)).padStart(2,'0')}:${String(x%60).padStart(2,'0')}`;}
